window.EXTRA_PLACES=[{"id":"heritage-3133","name":"Kobba Klintars lotsstation","loc":"Jo 33.1 · sjöfart","lat":60.03037326275121,"lon":19.88194824879477,"start":1862,"type":"pilot","category":"marine","text":"Lotsarna hjälpte fartyg att hitta säkert in till Mariehamn. Här fanns lotsstuga och senare ett större hus med en kraftig mistlur.","more":"lotsstation 1862–1972. Stationen och den gamla lotsstugan är från 1862. Det större lotshuset tillkom 1910. Lotsverksamheten slutade 1972, men byggnaderna finns kvar. Platsmarkören anger ett registerområde, inte byggnadens uppmätta läge.","dateLabel":"lotsstation 1862–1972","q":"Hur tror du att en lots lärde sig var grunden finns?","src":"heritage","sourceUrl":"https://kartor.regeringen.ax/arcgis/rest/services/Kulturarv/ByggnadsarvKulturmiljo/MapServer/4/query?where=KmID+%3D+%27Jo+33.1%27&outFields=%2A&returnGeometry=false&f=pjson","wiki":"https://sv.wikipedia.org/wiki/Kobba_Klintar"},{"id":"heritage-3164","name":"Rödhamns lotsstuga","loc":"Le 15.1 · sjöfart","lat":59.984061003954515,"lon":20.103711844996347,"start":1857,"type":"pilot","category":"marine","text":"Rödhamn var en viktig hamn före resan över Ålands hav. Lotsstugan byggdes 1857. Här fanns också en radiofyr som hjälpte sjöfarare fram till 1971.","more":"lotsstuga från 1857; verksamhet till början av 1930-talet. Registret anger att lotsverksamheten slutade i början av 1930-talet. Något exakt slutår anges inte. Platsmarkören anger ett registerområde, inte byggnadens uppmätta läge.","dateLabel":"lotsstuga från 1857; verksamhet till början av 1930-talet","q":"Hur tror du att en lots lärde sig var grunden finns?","src":"heritage","sourceUrl":"https://kartor.regeringen.ax/arcgis/rest/services/Kulturarv/ByggnadsarvKulturmiljo/MapServer/4/query?where=KmID+%3D+%27Le+15.1%27&outFields=%2A&returnGeometry=false&f=pjson","wiki":"https://sv.wikipedia.org/wiki/R%C3%B6dhamn"},{"id":"heritage-3144","name":"Espskärs lotsstation","loc":"Kö 4.3 · sjöfart","lat":59.89618741591695,"lon":20.89707583022374,"start":1857,"type":"pilot","category":"marine","text":"Från berget spanade lotsarna efter fartyg på väg mot Kökar. Lotsarna skötte också sjömärken och sjöräddning. Stationen stängde 1961.","more":"beslut om lotsstuga 1857; stationen stängde 1961. Beslutet om en lotsstuga fattades 1857. En annan källa anger 1877 som byggår, så dagens hus kan inte säkert dateras till 1857. Platsmarkören anger ett registerområde, inte byggnadens uppmätta läge.","dateLabel":"beslut om lotsstuga 1857; stationen stängde 1961","q":"Hur tror du att en lots lärde sig var grunden finns?","src":"heritage","sourceUrl":"https://kartor.regeringen.ax/arcgis/rest/services/Kulturarv/ByggnadsarvKulturmiljo/MapServer/4/query?where=KmID+%3D+%27K%C3%B6+4.3%27&outFields=%2A&returnGeometry=false&f=pjson","wiki":null},{"id":"heritage-3075","name":"Degerby – lots- och tullsamhälle","loc":"Fö 6.1 · sjöfart","lat":60.030779277217334,"lon":20.390082502164535,"start":1850,"type":"pilot","category":"marine","text":"Tullen flyttade till Degerby 1820 och lotsstationen följde efter 1850. Sjöfarten gjorde att byn växte med bostäder, packhus och andra byggnader.","more":"lotsstation från 1850. Markeringen avser Degerbys kulturmiljö och inte den exakta lotsstationsbyggnaden. När lotsverksamheten slutade är inte fastställt i detta underlag. Platsmarkören anger ett registerområde, inte byggnadens uppmätta läge.","dateLabel":"lotsstation från 1850","q":"Hur tror du att en lots lärde sig var grunden finns?","src":"heritage","sourceUrl":"https://kartor.regeringen.ax/arcgis/rest/services/Kulturarv/ByggnadsarvKulturmiljo/MapServer/4/query?where=KmID+%3D+%27F%C3%B6+6.1%27&outFields=%2A&returnGeometry=false&f=pjson","wiki":"https://sv.wikipedia.org/wiki/Degerby,_F%C3%B6gl%C3%B6"},{"id":"heritage-3085","name":"Dånö – lotsarnas by","loc":"Ge 3.1 · sjöfart","lat":60.400503209447216,"lon":19.773149402582764,"start":1850,"type":"pilot","category":"marine","text":"Lotsar bodde i Dånö och höll utkik från en stuga på berget. Ett äldre lotshem i byn blev senare hembygdsmuseum.","more":"lotsstuga från senare delen av 1800-talet; stängd på 1920-talet. Lotsstugan uppfördes under senare delen av 1800-talet. Tidslinjens start vid 1850 är ungefärlig. Markeringen avser Dånös kulturmiljö. Platsmarkören anger ett registerområde, inte byggnadens uppmätta läge.","dateLabel":"lotsstuga från senare delen av 1800-talet; stängd på 1920-talet","q":"Hur tror du att en lots lärde sig var grunden finns?","src":"heritage","sourceUrl":"https://kartor.regeringen.ax/arcgis/rest/services/Kulturarv/ByggnadsarvKulturmiljo/MapServer/4/query?where=KmID+%3D+%27Ge+3.1%27&outFields=%2A&returnGeometry=false&f=pjson","wiki":"https://sv.wikipedia.org/wiki/D%C3%A5n%C3%B6"},{"id":"heritage-3149","name":"Mosshaga lotsplats","loc":"So 4.1 · sjöfart","lat":60.16295931295027,"lon":20.593596418289874,"start":1740,"type":"pilot","category":"marine","text":"Mosshaga låg vid en viktig farled. Lotsarna hjälpte fartygen förbi och öborna förde också post genom skärgården. Lotsplatsen lades ned 1918.","more":"lotsplats från 1740-talet till 1918. Lotsplatsen etablerades under 1740-talet; exakt år är inte känt. Markeringen avser den historiska bymiljön. Platsmarkören anger ett registerområde, inte byggnadens uppmätta läge.","dateLabel":"lotsplats från 1740-talet till 1918","q":"Hur tror du att en lots lärde sig var grunden finns?","src":"heritage","sourceUrl":"https://kartor.regeringen.ax/arcgis/rest/services/Kulturarv/ByggnadsarvKulturmiljo/MapServer/4/query?where=KmID+%3D+%27So+4.1%27&outFields=%2A&returnGeometry=false&f=pjson","wiki":"https://sv.wikipedia.org/wiki/Mosshaga"},{"id":"heritage-3105","name":"Sälskärs fyrplats","loc":"Ha 45.1 · sjöfart","lat":60.41103588874849,"lon":19.59760657422837,"start":1868,"type":"pilot","category":"marine","text":"Fyren hjälpte fartyg ute vid Bottenhavet. På ön bodde fyrvaktare med sina familjer. År 1949 blev fyren automatisk och personalen flyttade.","more":"fyr från 1868; bemannad till 1949. Markeringen avser fyrplatsens kulturmiljö. Bemanningen upphörde 1949, men fyren finns kvar. Platsmarkören anger ett registerområde, inte byggnadens uppmätta läge.","dateLabel":"fyr från 1868; bemannad till 1949","q":"Hur tror du att en lots lärde sig var grunden finns?","src":"heritage","sourceUrl":"https://kartor.regeringen.ax/arcgis/rest/services/Kulturarv/ByggnadsarvKulturmiljo/MapServer/4/query?where=KmID+%3D+%27Ha+45.1%27&outFields=%2A&returnGeometry=false&f=pjson","wiki":"https://sv.wikipedia.org/wiki/S%C3%A4lsk%C3%A4r"}];
